query:
SELECT COUNT(DISTINCT cliente_id) as clientes_unicos_maio
FROM faturamentos 
WHERE MONTH(STR_TO_DATE(data, '%Y-%m-%d')) = 5 AND YEAR(STR_TO_DATE(data, '%Y-%m-%d')) = 2026;

